#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" — clear the screen, then announce a stage and show progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=6

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$ROOT"
ENV_FILE="${AUTH0_WIZARD_ENV_FILE:-$ROOT/.env.auth0.local}"
umask 077

banner "Height Safety — Auth0 owner setup"

stage "Auth0 tenant — confirm locality"
say "Use the tenant you intend for this environment. The repository's physical test used a US development tenant; the selected pilot target is an AU tenant."
open_url "https://manage.auth0.com/"
step "In the Auth0 Dashboard, select the tenant and copy its Domain (hostname only; do not include https:// or a path)."
ask AUTH0_DOMAIN "Tenant domain:"
AUTH0_DOMAIN="${AUTH0_DOMAIN#https://}"
AUTH0_DOMAIN="${AUTH0_DOMAIN#http://}"
AUTH0_DOMAIN="${AUTH0_DOMAIN%/}"
[[ -n "$AUTH0_DOMAIN" ]] || { warn "A tenant domain is required."; exit 1; }
[[ "$AUTH0_DOMAIN" != */* ]] || { warn "Enter the Auth0 hostname only; remove any path."; exit 1; }
if [[ "$AUTH0_DOMAIN" == *.us.auth0.com ]]; then
  warn "This is a US Auth0 domain. Keep it for local development if desired, but it does not close the AU pilot-tenant action."
elif [[ "$AUTH0_DOMAIN" != *.au.auth0.com ]]; then
  warn "The domain is not the usual *.au.auth0.com form. Confirm the tenant's Australian locality or an approved custom-domain arrangement before using it for the pilot."
fi
write_env AUTH0_DOMAIN "$AUTH0_DOMAIN"
pause "Confirm the selected tenant is the one you want to configure."

stage "Auth0 API and applications"
say "Create or verify one API, one Regular Web Application and one Native Android Application in this tenant. Existing entries may be kept if their values match."
open_url "https://manage.auth0.com/"
step "API: create/select the API and record its stable Identifier. This becomes AUTH0_API_AUDIENCE; do not use the Auth0 Management API as the audience."
ask AUTH0_API_AUDIENCE "Stable API audience/identifier:"
step "Regular Web Application: add this exact Allowed Callback URL: http://localhost:3000/auth/callback"
step "Regular Web Application: add this exact Allowed Logout URL: http://localhost:3000"
step "Regular Web Application: copy its Client ID, then reveal/copy its Client Secret."
ask AUTH0_CLIENT_ID "Web application client ID:"
ask_secret AUTH0_CLIENT_SECRET "Web application client secret:"
step "Native Android Application: set the callback to https://${AUTH0_DOMAIN}/android/au.com.heightsafety.app/callback (the package name is au.com.heightsafety.app). Use the same URL for native logout if the dashboard asks for one."
step "Native Android Application: copy its public Client ID. Never put the web client secret in the Android build."
ask ANDROID_NATIVE_CLIENT_ID "Native Android client ID:"
[[ -n "$AUTH0_API_AUDIENCE" && -n "$AUTH0_CLIENT_ID" && -n "$AUTH0_CLIENT_SECRET" && -n "$ANDROID_NATIVE_CLIENT_ID" ]] || { warn "API audience, both client IDs and the web client secret are required."; exit 1; }
write_env AUTH0_API_AUDIENCE "$AUTH0_API_AUDIENCE"
write_env AUTH0_CLIENT_ID "$AUTH0_CLIENT_ID"
write_env AUTH0_CLIENT_SECRET "$AUTH0_CLIENT_SECRET"
write_env ANDROID_NATIVE_CLIENT_ID "$ANDROID_NATIVE_CLIENT_ID"
chmod 600 "$ENV_FILE"
pause "Confirm the dashboard saved all URL and application changes."

stage "Verified email and administrator MFA"
say "Configure security in the selected tenant, then test the owner account before proceeding."
open_url "https://manage.auth0.com/"
step "Enable a verified-email flow for the connection used by this application. Complete verification for the test account; the API rejects unverified identities."
step "Dashboard → Security → Multi-factor Auth: enable at least one factor and choose a policy that requires MFA for administrator access. For the prototype, an Always policy is the simplest auditable choice; it may also prompt inspectors/reviewers."
step "Enroll the owner/administrator in the chosen factor and verify that a fresh login actually completes the challenge. Keep recovery codes in your password manager, not this repository."
pause "When verified email and administrator MFA are tested, press Enter."

stage "Stable MFA claim/action"
say "Add a versioned Post-Login Action that writes a boolean access-token claim. Keep this namespace unchanged because the API defaults to it."
open_url "https://auth0.com/docs/secure/multi-factor-authentication/customize-mfa/customize-mfa-selection-universal-login"
step "Dashboard → Actions → Flows → Login → Add Action → Build from scratch; choose Login / Post-Login and the recommended Node runtime."
step "The Action should set access-token claim https://height-safety.example/claims/mfa_satisfied to true only when event.authentication.methods contains a method whose name is mfa; otherwise set it to false or omit it. If another Action invokes challengeWith/challengeWithAny, place this claim Action after it."
step "Deploy the Action and attach it to the Login flow. Run the Auth0 Action test/login flow and inspect the resulting access token or tenant log; do not paste the token here."
write_env AUTH0_MFA_CLAIM "https://height-safety.example/claims/mfa_satisfied"
pause "Confirm the Action is deployed, attached to Login, and the claim appears after an MFA login."

stage "Local runtime secrets"
say "The ignored local file stores values for your shell. It is not committed and is not sent to Android."
if command -v openssl >/dev/null 2>&1; then
  current_secret=$(_existing AUTH0_SECRET || true)
  if [[ -n "$current_secret" ]]; then
    AUTH0_SECRET="$current_secret"
    note "Keeping the existing AUTH0_SECRET in $ENV_FILE."
  else
    AUTH0_SECRET="$(openssl rand -hex 32)"
    note "Generated a new AUTH0_SECRET locally; it will not be printed."
  fi
else
  ask_secret AUTH0_SECRET "Generate/provide a 32-byte hex AUTH0_SECRET:"
fi
ask APP_BASE_URL "Office base URL [http://localhost:3000]:"
[[ -n "$APP_BASE_URL" ]] || APP_BASE_URL="http://localhost:3000"
write_env AUTH0_SECRET "$AUTH0_SECRET"
write_env APP_BASE_URL "$APP_BASE_URL"
write_env AUTH0_EMAIL_CLAIM "email"
write_env AUTH0_EMAIL_VERIFIED_CLAIM "email_verified"
write_env AUTH0_USE_USERINFO "true"
chmod 600 "$ENV_FILE"
note "Before starting API/web locally: set -a; source $ENV_FILE; set +a"
warn "Never commit this file, paste it into chat, or pass AUTH0_CLIENT_SECRET/AUTH0_SECRET to Gradle or Android."
pause "Confirm the file is stored locally or copied into your approved secret manager."

stage "Invitation delivery and physical Pixel acceptance"
say "Invitation delivery is an owner-provisioned private mail/messaging endpoint, not an Auth0 dashboard setting. It may remain unconfigured for login testing, but invitations fail closed until it exists."
open_url "https://auth0.com/docs/api/management/v2/organizations/post-invitations"
step "If you already have a private HTTPS adapter, configure it to accept the application's one-time invitation payload and authenticate it with a bearer token. Keep any Auth0 Management API credential inside that server-side adapter."
if confirm "Configure an invitation-delivery endpoint now?"; then
  ask INVITATION_DELIVERY_URL "Private HTTPS delivery endpoint URL:"
  ask_secret INVITATION_DELIVERY_TOKEN "Bearer token for that endpoint:"
  ask INVITATION_DELIVERY_TIMEOUT_MS "Delivery timeout in milliseconds [10000]:"
  [[ -n "$INVITATION_DELIVERY_TIMEOUT_MS" ]] || INVITATION_DELIVERY_TIMEOUT_MS="10000"
  [[ -n "$INVITATION_DELIVERY_URL" && -n "$INVITATION_DELIVERY_TOKEN" ]] || { warn "Endpoint and token must be supplied together; leaving delivery unconfigured."; }
  if [[ -n "$INVITATION_DELIVERY_URL" && -n "$INVITATION_DELIVERY_TOKEN" ]]; then
    write_env INVITATION_DELIVERY_URL "$INVITATION_DELIVERY_URL"
    write_env INVITATION_DELIVERY_TOKEN "$INVITATION_DELIVERY_TOKEN"
    write_env INVITATION_DELIVERY_TIMEOUT_MS "$INVITATION_DELIVERY_TIMEOUT_MS"
    chmod 600 "$ENV_FILE"
  fi
else
  note "Invitation delivery remains intentionally fail-closed until an owner endpoint is provisioned."
fi
step "For the physical Pixel test, keep the computer and Pixel on the same Wi-Fi, run the API on HOST=0.0.0.0, and build Android with only AUTH0_DOMAIN, ANDROID_NATIVE_CLIENT_ID, AUTH0_API_AUDIENCE and the computer's LAN API URL."
step "Sign in with a verified Inspector account; confirm Company: aaa and the seeded QLD job pack. Lock/resume, capture a mutation and photo offline, restart the app, reconnect and confirm the mutation acknowledgement and photo upload."
step "If a reviewer account is available, create and resolve one review issue with a reason; confirm the inspector evidence is unchanged and the action is visible."
ask ANDROID_SERIAL "Pixel adb serial (for your local notes, optional):"
ask API_LAN_IP "Computer LAN IP used by the Pixel (for your local notes, optional):"
write_env ANDROID_SERIAL "$ANDROID_SERIAL"
write_env API_LAN_IP "$API_LAN_IP"
chmod 600 "$ENV_FILE"
note "Report only pass/fail and non-secret configuration facts back to the project. Never report tokens, client secrets, AUTH0_SECRET, database passwords or recovery codes."

finish
